pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let result = match input {
        serde_json::Value::String(s) => {
            let mut output = String::new();
            for c in s.chars() {
                if c.is_ascii() {
                    if c.is_ascii_uppercase() {
                        let rotated = ((c as u8 - b'A' + 13) % 26) + b'A';
                        output.push(rotated as char);
                    } else if c.is_ascii_lowercase() {
                        let rotated = ((c as u8 - b'a' + 13) % 26) + b'a';
                        output.push(rotated as char);
                    } else {
                        output.push(c);
                    }
                } else {
                    output.push(c);
                }
            }
            serde_json::Value::String(output)
        }
        serde_json::Value::Array(arr) => {
            let mut result_array = Vec::new();
            for item in arr {
                result_array.push(solve(item));
            }
            serde_json::Value::Array(result_array)
        }
        serde_json::Value::Object(obj) => {
            let mut result_object = std::collections::HashMap::new();
            for (k, v) in obj {
                result_object.insert(k, solve(v));
            }
            serde_json::Value::Object(result_object)
        }
        serde_json::Value::Null => serde_json::Value::Null,
        serde_json::Value::Bool(b) => serde_json::Value::Bool(b),
    };
    result
}
